/// Returns the sign of the given 32-bit integer:
/// -  1 if x > 0
/// -  0 if x == 0
/// - -1 if x < 0
fn sign_of(x: i32) -> i32 {
    if x > 0 {
        1
    } else if x < 0 {
        -1
    } else {
        0
    }
}

/// Given a vector of 32-bit integers, returns a new vector where each element
/// is replaced by its sign (using `sign_of`), preserving the original order.
fn sign(a: Vec<i32>) -> Vec<i32> {
    a.into_iter().map(sign_of).collect()
}

